<script setup lang="ts">
import type {SubscriptionAlertPolicy,LowQuotaThreshold} from '@papilio/api';
import {useI18n} from 'vue-i18n';
const model=defineModel<SubscriptionAlertPolicy>({required:true});
const {t}=useI18n();
function threshold(rule:LowQuotaThreshold,key:"remaining_percent_bps"|"remaining_bytes",event:Event):void{const value=(event.target as HTMLInputElement).value;rule[key]=value===""?null:Number(value);}
function add():void{model.value.low_quota.push({code:'',mode:'any',remaining_percent_bps:null,remaining_bytes:null});}
</script>
<template><fieldset class="form-grid"><legend>{{t('settingsEditors.alerts.title')}}</legend><label class="check-row"><input v-model="model.enabled" type="checkbox"/>{{t('settingsEditors.alerts.enable')}}</label><p class="hint-box">{{t('settingsEditors.alerts.hint')}}</p><fieldset v-for="(rule,index) in model.low_quota" :key="index" class="form-grid"><legend>{{t('settingsEditors.alerts.rule',{index:index+1})}}</legend><label class="field"><span>{{t('settingsEditors.alerts.code')}}</span><input v-model="rule.code" required maxlength="32" pattern="[A-Za-z0-9_-]+"/></label><label class="field"><span>{{t('settingsEditors.alerts.combination')}}</span><select v-model="rule.mode"><option value="any">{{t('settingsEditors.alerts.any')}}</option><option value="all">{{t('settingsEditors.alerts.all')}}</option></select></label><label class="field"><span>{{t('settingsEditors.alerts.percent')}}</span><input :value="rule.remaining_percent_bps??''" type="number" min="0" max="10000" :placeholder="t('settingsEditors.alerts.unset')" @input="threshold(rule,'remaining_percent_bps',$event)"/></label><label class="field"><span>{{t('settingsEditors.alerts.bytes')}}</span><input :value="rule.remaining_bytes??''" type="number" min="0" :placeholder="t('settingsEditors.alerts.unset')" @input="threshold(rule,'remaining_bytes',$event)"/></label><button type="button" class="btn secondary" @click="model.low_quota.splice(index,1)">{{t('settingsEditors.alerts.removeQuota')}}</button></fieldset><button type="button" class="btn secondary" @click="add">{{t('settingsEditors.alerts.addQuota')}}</button><label v-for="(_,index) in model.expiry_hours" :key="index" class="field"><span>{{t('settingsEditors.alerts.expiry',{index:index+1})}}</span><input v-model.number="model.expiry_hours[index]" required type="number" min="1"/><button type="button" class="btn secondary" @click="model.expiry_hours.splice(index,1)">{{t('settingsEditors.alerts.removeExpiry')}}</button></label><button type="button" class="btn secondary" @click="model.expiry_hours.push(1)">{{t('settingsEditors.alerts.addExpiry')}}</button><label class="check-row"><input v-model="model.renewal_opportunity" type="checkbox"/>{{t('settingsEditors.alerts.renewal')}}</label><p>{{t('settingsEditors.alerts.footer')}}</p></fieldset></template>
